#version 300
uniform shader image;
uniform float2 size;
uniform float2 layer;
uniform float3x3 fromLayer;
uniform float3x3 toLayer;
uniform float4 screen;
uniform float time;
float2 amzCoord;
float4 amzOutput;
float2 amzScreenNorm() { float2 p=amzCoord-screen.xy; return float2(p.x/screen.z,1.0-p.y/screen.w); }
float2 amzLayerNorm() { float3 p=toLayer*float3(amzCoord,1.0); float2 n=p.xy/p.z/layer; return float2(n.x,1.0-n.y); }
float2 amzLayerCenter() { float3 p=fromLayer*float3(layer*.5,1.0); return p.xy/p.z-screen.xy; }
float4x4 amzRowMatrix(float3x3 m) { return float4x4(m[0].x,m[1].x,0.0,m[2].x, m[0].y,m[1].y,0.0,m[2].y, 0.0,0.0,1.0,0.0, m[0].z,m[1].z,0.0,m[2].z); }
float4x4 amzLayerToScreen() {
    float3x3 toNorm=float3x3(1.0/screen.z,0.0,0.0, 0.0,-1.0/screen.w,0.0,-screen.x/screen.z,1.0+screen.y/screen.w,1.0);
    float3x3 toPixels=float3x3(layer.x,0.0,0.0, 0.0,-layer.y,0.0, 0.0,layer.y,1.0);
    return amzRowMatrix(toNorm*fromLayer*toPixels);
}
float4x4 amzScreenToLayer() {
    float3x3 toPixels=float3x3(screen.z,0.0,0.0, 0.0,-screen.w,0.0, screen.x,screen.y+screen.w,1.0);
    float3x3 toNorm=float3x3(1.0/layer.x,0.0,0.0, 0.0,-1.0/layer.y,0.0,0.0,1.0,1.0);
    return amzRowMatrix(toNorm*toLayer*toPixels);
}
float2 getTexSize(float2 v) { return v; }
int amzIntMax(int a,int b) { return int(max(float(a),float(b))); }
int amzIntMin(int a,int b) { return int(min(float(a),float(b))); }
int amzIntAbs(int a) { return int(abs(float(a))); }
int amzIntClamp(int a,int b,int c) { return int(clamp(float(a),float(b),float(c))); }
uniform float2 amzVelocity,amzPivot,amzScale;
uniform float amzAngularVelocity,amzScaleVelocity,amzStartTime,amzEndTime;

struct AC_ImageInfo { int texture; float2 amzLocal_size; };
const float3x3 labPlaneInverse=float3x3(1);
float4x4 amzQuaternion(float4 q) {
    q /= max(length(q),0.000001);
    float x=q.x,y=q.y,z=q.z,w=q.w;
    return float4x4(1-2*(y*y+z*z),2*(x*y+w*z),2*(x*z-w*y),0,
                    2*(x*y-w*z),1-2*(x*x+z*z),2*(y*z+w*x),0,
                    2*(x*z+w*y),2*(y*z-w*x),1-2*(x*x+y*y),0,0,0,0,1);
}
const int amzPass=0;
uniform float amzIteration;
float4 amzSample_inputImg(float2 uv) { return float4(image.eval(((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0))); }
float4 amzTexture(int tex,float2 uv) { if(tex==0) return amzSample_inputImg(uv);return float4(0.0); }
float4 amzTexture(int tex,float2 uv,float bias){return amzTexture(tex,uv);}
uniform float amzp_octaves;
uniform float amzp_scale;
uniform float amzp_lacunarity;
uniform float amzp_gain;
uniform float amzp_timeSpeed;
uniform float amzp_seed;
uniform float amzp_colorizeHSV;
uniform float amzp_hueScale;
uniform float amzp_saturation;
uniform float amzp_value;
uniform float amzp_blend;
uniform float amzp_alpha;




    float hash11(float n) {
      return fract(sin(n) * 43758.5453123);
    }
    float hash21(float2 p) {
      return fract(sin(dot(p, float2(127.1, 311.7))) * 43758.5453123);
    }
    float hash31(float3 p) {
      return fract(sin(dot(p, float3(127.1, 311.7, 74.7))) * 43758.5453123);
    }


    float2 randVec2(float2 p){
      float a = hash21(p) * 6.28318530718; 
      return float2(cos(a), sin(a));
    }
    float3 randVec3(float3 p){
      float a = hash31(p);
      float b = hash31(p + 17.17);
      float theta = a * 6.28318530718;
      float phi = acos(1.0 - 2.0 * b);
      return float3(sin(phi)*cos(theta), sin(phi)*sin(theta), cos(phi));
    }


    float2 smooth2(float2 x){ return x*x*x*((6.0*x - 15.0)*x + 10.0); }
    float3 smooth3(float3 x){ return x*x*x*((6.0*x - 15.0)*x + 10.0); }


    float perlin2(float2 p){
      float2 ip = floor(p);
      float2 f = fract(p);
      float2 u = smooth2(f);

      float2 g00 = randVec2(ip);
      float2 g10 = randVec2(ip + float2(1.0, 0.0));
      float2 g01 = randVec2(ip + float2(0.0, 1.0));
      float2 g11 = randVec2(ip + float2(1.0, 1.0));

      float n00 = dot(g00, f);
      float n10 = dot(g10, f - float2(1.0, 0.0));
      float n01 = dot(g01, f - float2(0.0, 1.0));
      float n11 = dot(g11, f - float2(1.0, 1.0));

      float nx0 = mix(n00, n10, u.x);
      float nx1 = mix(n01, n11, u.x);
      float nxy = mix(nx0, nx1, u.y);

      return nxy * 1.41421356 * 0.5 + 0.5;
    }


    float perlin3(float3 p){
      float3 ip = floor(p);
      float3 f = fract(p);
      float3 u = smooth3(f);

      float3 g000 = randVec3(ip);
      float3 g100 = randVec3(ip + float3(1.0, 0.0, 0.0));
      float3 g010 = randVec3(ip + float3(0.0, 1.0, 0.0));
      float3 g110 = randVec3(ip + float3(1.0, 1.0, 0.0));
      float3 g001 = randVec3(ip + float3(0.0, 0.0, 1.0));
      float3 g101 = randVec3(ip + float3(1.0, 0.0, 1.0));
      float3 g011 = randVec3(ip + float3(0.0, 1.0, 1.0));
      float3 g111 = randVec3(ip + float3(1.0, 1.0, 1.0));

      float n000 = dot(g000, f);
      float n100 = dot(g100, f - float3(1.0, 0.0, 0.0));
      float n010 = dot(g010, f - float3(0.0, 1.0, 0.0));
      float n110 = dot(g110, f - float3(1.0, 1.0, 0.0));
      float n001 = dot(g001, f - float3(0.0, 0.0, 1.0));
      float n101 = dot(g101, f - float3(1.0, 0.0, 1.0));
      float n011 = dot(g011, f - float3(0.0, 1.0, 1.0));
      float n111 = dot(g111, f - float3(1.0, 1.0, 1.0));

      float nx00 = mix(n000, n100, u.x);
      float nx10 = mix(n010, n110, u.x);
      float nx01 = mix(n001, n101, u.x);
      float nx11 = mix(n011, n111, u.x);
      float nxy0 = mix(nx00, nx10, u.y);
      float nxy1 = mix(nx01, nx11, u.y);
      float nxyz = mix(nxy0, nxy1, u.z);

      return nxyz * 1.154700538 * 0.5 + 0.5;
    }


    float fbm2(float2 p, int oct){
      float sum = 0.0;
      float amp = 1.0;
      float tot = 0.0;
      float freq = 1.0;
      for(int i=0;i<8;i++){
        if(i>=oct) break;
        sum += perlin2(p*freq) * amp;
        tot += amp;
        freq *= amzp_lacunarity;
        amp *= amzp_gain;
      }
      return sum / max(tot, 1e-6);
    }
    float fbm3(float3 p, int oct){
      float sum = 0.0;
      float amp = 1.0;
      float tot = 0.0;
      float freq = 1.0;
      for(int i=0;i<8;i++){
        if(i>=oct) break;
        sum += perlin3(p*freq) * amp;
        tot += amp;
        freq *= amzp_lacunarity;
        amp *= amzp_gain;
      }
      return sum / max(tot, 1e-6);
    }

    float3 hsv2rgb(float3 c){
      float4 K = float4(1.0, 2.0/3.0, 1.0/3.0, 3.0);
      float3 p = abs(fract(c.xxx + K.xyz) * 6.0 - K.www);
      return c.z * mix(K.xxx, clamp(p - K.xxx, 0.0, 1.0), c.y);
    }

    void amzRender(){

      float2 uv = amzScreenNorm();
      uv.x *= screen.zw.x / screen.zw.y;

      int oct = int(clamp(float(amzp_octaves), 1.0, 8.0));
      float t = time * amzp_timeSpeed;
      float3 p3 = float3(uv * amzp_scale + amzp_seed, t);
      float n = fbm3(p3, oct);

      float3 col;
      if((amzp_colorizeHSV>0.5)){
        col = hsv2rgb(float3(n * amzp_hueScale, clamp(amzp_saturation,0.0,1.0), amzp_value));
      } else {
        col = float3(n);
      }

      float4 src = amzTexture(0, amzScreenNorm());
      float3 outRGB = mix(src.rgb, col, clamp(amzp_blend, 0.0, 1.0));
      float a = src.a * amzp_alpha;
      amzOutput = float4(outRGB, 1.0) * a;
    }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }

